@Observable final class Profile { var name = ""; var notifications = true }

struct ProfileScreen: View {
    @State private var profile = Profile()     // owns the model
    @State private var showHelp = false        // owns a simple value

    var body: some View {
        Form {
            NameField(profile: profile)
            SettingsToggle(isOn: $showHelp)    // pass a binding
        }
        .environment(profile)                  // available to all children
    }
}

struct NameField: View {
    @Bindable var profile: Profile             // to get $profile.name
    var body: some View { TextField("Name", text: $profile.name) }
}

struct SettingsToggle: View {
    @Binding var isOn: Bool                    // borrowed, can write
    var body: some View { Toggle("Show help", isOn: $isOn) }
}
